harness.depth_surface_reader:
() => {
  const data = JSON.parse(document.querySelector(".ladder-panel .evidence pre").textContent);
  const scroll = document.querySelector(".ladder-scroll"), box = scroll.getBoundingClientRect();
  return { data, cap: document.querySelector(".dom-scale .number").title, unit: document.querySelector('[aria-label="DOM quantity units"]').value, cumulative: document.querySelector('[aria-label="Cumulative depth"]').checked, following: document.querySelector('[aria-label="Follow midpoint"]').checked, frozen: document.querySelector('[data-testid="dom-freeze"]').getAttribute("aria-pressed") === "true", scrollTop: scroll.scrollTop, scrollHeight: scroll.scrollHeight, clientHeight: scroll.clientHeight, status: document.querySelector(".dom-status").textContent, spread: [...document.querySelectorAll(".dom-spread .number")].map((e) => e.title), rows: [...document.querySelectorAll(".ladder tr[data-side]")].map((row) => {
    const r = row.getBoundingClientRect();
    return { side: row.dataset.side, price: row.dataset.price, values: [...row.querySelectorAll(".number")].map((e) => e.title), bar: !!row.querySelector(".dom-depth-bar"), width: parseFloat(row.querySelector(".dom-quantity").style.getPropertyValue("--depth-width")), classes: row.className, visible: r.bottom > box.top + 26 && r.top < box.bottom };
  }) };
}

harness.finite_native_probe:
async ({ page }, reader, sessionId, root) => {
  const ensure = (condition, message) => {
    if (!condition)
      throw Error(message);
  };
  const read = () => page.evaluate(reader);
  const validate = (s) => {
    const map = new Map(s.data.rows.map((row) => [row.side + ":" + row.price, row]));
    for (const row of s.rows) {
      const native = map.get(row.side + ":" + row.price);
      const quantity = s.unit === "base" ? native.base_quantity : native.quote_notional;
      ensure(row.values[0] === native.price && row.values[1] === quantity, "Economic display changed native strings");
      if (s.cumulative)
        ensure(row.values[2] === (s.unit === "base" ? native.cumulative_base : native.cumulative_quote), "Cumulative unit mismatch");
      if (s.data.eligible) {
        ensure(row.bar, "Eligible row lost its depth bar");
        ensure(Math.abs(row.width - Math.min(1, Number(quantity) / Number(s.cap)) * 100) < 0.00011, "Side depth bars do not share the held native cap");
      }
    }
    if (s.data.summary)
      ensure(JSON.stringify(s.spread) === JSON.stringify([s.data.summary.midpoint, s.data.summary.spread, s.data.summary.spread_ticks ?? "—", s.data.summary.spread_bps]), "Spread display changed native evidence");
  };
  const first = await read();
  validate(first);
  const samples = [];
  const started = Date.now();
  while (Date.now() - started < 60000) {
    const s = await read();
    validate(s);
    ensure(s.cap === first.cap, "Incoming updates rescaled depth bars");
    ensure(s.following, "Automatic updates unexpectedly suspended follow");
    samples.push({ elapsed_ms: Date.now() - started, asof: s.data.asof, eligible: s.data.eligible, reasons: s.data.reasons, cap: s.cap, highlighted: s.rows.filter((row) => /dom-(addition|removal)/.test(row.classes)).length });
    await new Promise((resolve) => setTimeout(resolve, 1000));
  }
  await page.click('[data-testid="dom-freeze"]');
  await page.waitForFunction(() => document.querySelector('[data-testid="dom-freeze"]').getAttribute("aria-pressed") === "true");
  const frozenBase = await read();
  await page.select('[aria-label="DOM quantity units"]', "quote");
  if (!await page.$eval('[aria-label="Cumulative depth"]', (e) => e.checked))
    await page.click('[aria-label="Cumulative depth"]');
  await page.waitForFunction(() => document.querySelectorAll(".ladder tr[data-side]")[0]?.querySelectorAll(".number").length === 3);
  const quote = await read();
  validate(quote);
  ensure(JSON.stringify(quote.data) === JSON.stringify(frozenBase.data), "Unit toggle replaced frozen native evidence");
  await page.click(".dom-scale button");
  const rescaled = await read();
  ensure(Number(rescaled.cap) === Math.max(...rescaled.data.rows.map((row) => Number(row.quote_notional))), "Explicit rescale did not capture both-side maximum");
  const tape = await page.$eval(".tape-scroll tbody", (e) => e.textContent);
  await page.waitForFunction((old) => document.querySelector(".tape-scroll tbody").textContent !== old, { timeout: 20000 }, tape);
  ensure(JSON.stringify((await read()).data) === JSON.stringify(quote.data), "Frozen DOM changed while tape advanced");
  const scroll = await page.$(".ladder-scroll"), box = await scroll.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  const oldTop = (await read()).scrollTop;
  await page.mouse.wheel({ deltaY: -200 });
  await page.waitForFunction((old) => !document.querySelector('[aria-label="Follow midpoint"]').checked && document.querySelector(".ladder-scroll").scrollTop < old, {}, oldTop);
  const manual = (await read()).scrollTop;
  await page.select('[aria-label="Ladder rows"]', "50");
  await page.waitForFunction(() => JSON.parse(document.querySelector(".ladder-panel .evidence pre").textContent).rows.length === 100);
  await page.focus('[aria-label="DOM width"]');
  await page.keyboard.press("ArrowLeft");
  await page.keyboard.press("ArrowLeft");
  const manualAfter = await read();
  ensure(!manualAfter.following && Math.abs(manualAfter.scrollTop - manual) < 1, "Resize or row scope overrode manual scroll");
  await page.click(".ladder-panel .tabs button:last-child");
  const recentered = await read();
  ensure(recentered.following && ["bid", "ask"].every((side) => recentered.rows.some((row) => row.side === side && row.visible && row.classes.includes("dom-best"))), "Recenter failed to restore both best buckets");
  await page.screenshot({ path: root + "depth-ladder-binance-quote.png", fullPage: true });
  const frame = await page.evaluate(async (id) => {
    const response = await fetch("/api/v1/sessions/" + id);
    if (!response.ok)
      throw Error("Session frame " + response.status);
    return await response.json();
  }, sessionId);
  ensure(frame.status === "live" && !frame.source.synthetic && frame.telemetry.overflows === 0, "Native live stream lost integrity");
  await page.click('[data-testid="dom-freeze"]');
  return { first, samples, frozenBase, quote, rescaled, manual: { before: manual, after: manualAfter.scrollTop }, recentered, frame: { session_id: frame.session_id, status: frame.status, selection: frame.selection, health: frame.health, coverage: frame.book.quality.coverage, revision: frame.book.revision, telemetry: frame.telemetry }, elapsed_ms: Date.now() - started };
}
